    public static InMemoryJobStore create() throws HaciendaRsException {
        try {
            Throwable operationFailure = null;
            try {
            var handle = (MemorySegment) NativeLib.HACIENDA_IN_MEMORY_JOB_STORE_NEW.invoke();
            if (handle == null || handle.equals(MemorySegment.NULL)) {
                throw new HaciendaRsException("create returned null", (Throwable) null);
            }
            return new InMemoryJobStore(handle);
            } catch (Throwable failure) {
                operationFailure = failure;
                throw failure;
            } finally {
            }
        }
        catch (Throwable e) {
            if (e instanceof HaciendaRsException) throw (HaciendaRsException) e;
            throw new RuntimeException("create failed: " + e.getMessage(), e);
        }
    }
    @Override
    @SuppressWarnings("PMD.AvoidCatchingGenericException")
    public synchronized void close() {
        if (transferPending) {
            awaitTransfer();
        }
        if (handleUnavailable || handle == null || handle.equals(MemorySegment.NULL)) {
            handleUnavailable = true;
            return;
        }
        handleUnavailable = true;
        awaitBorrowedCalls();
        MemorySegment handleToFree = handle;
        handle = MemorySegment.NULL;
        try {
            NativeLib.HACIENDA_IN_MEMORY_JOB_STORE_FREE.invoke(handleToFree);
        } catch (Throwable e) {
            throw new RuntimeException("Failed to free InMemoryJobStore: " + e.getMessage(), e);
        }
    }

    private void awaitTransfer() {
        boolean interrupted = false;
        while (transferPending) {
            try {
                wait();
            } catch (InterruptedException ignored) {
                interrupted = true;
            }
        }
        if (interrupted) {
            Thread.currentThread().interrupt();
        }
    }

    // CPD-OFF — generated FFI boilerplate, identical across all opaque types by design.
    private static void checkLastFfiError() throws HaciendaRsException {
        try {
            int code = (int)(long) NativeLib.HACIENDA_LAST_ERROR_CODE.invoke();
            if (code == 0) { return; }
            MemorySegment ctxPtr = (MemorySegment) NativeLib.HACIENDA_LAST_ERROR_CONTEXT.invoke();
            String msg = ctxPtr.equals(MemorySegment.NULL) ? "unknown" : ctxPtr.reinterpret(Long.MAX_VALUE).getString(0);
            throw NativeLib.lastErrorException(code, msg);
        } catch (HaciendaRsException e) {
            throw e;
        } catch (Throwable e) {
            throw new HaciendaRsException("failed to read last error", e);
        }
    }
    private static final ObjectMapper STREAM_MAPPER = createStreamMapper();

    private static ObjectMapper createStreamMapper() {
        var mapper = new ObjectMapper()
            .registerModule(new com.fasterxml.jackson.datatype.jdk8.Jdk8Module())
            .findAndRegisterModules()
            .setPropertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE)
            .setSerializationInclusion(com.fasterxml.jackson.annotation.JsonInclude.Include.NON_NULL)
            .configure(com.fasterxml.jackson.databind.MapperFeature.ACCEPT_CASE_INSENSITIVE_ENUMS, true);
        return JsonMapperFactory.withNativePathSerialization(mapper);
    }    // CPD-ON
